106:      * @param {string} itemTitle - The title for this item.
107:      * @param {string} itemTime - The formatted time for this item.
108:      * @returns {Element} the completed tr.
109:      */
110:     function makeHistoryRow(itemUrl, itemTitle, itemTime) {
111:         var row = document.createElement("tr");
