134:     /**
135:      * Get JSON from given URL.
136:      *
137:      * @param {string} url - the url to fetch data from.
138:      * @param {function} callback - the function to callback with data.
139:      * @returns {void}
140:      */
141:     function getJSON(url, callback) {
142:         var xhr = new XMLHttpRequest();
143:         xhr.open("GET", url, true);
144:         xhr.responseType = "json";
145:         xhr.onload = function() {
146:             var status = xhr.status;
147:             callback(status, xhr.response);
148:         };
149:         xhr.send();
150:     }
151: 
152:     /**
153:      * Receive history data from qute://history/data.
154:      *
155:      * @param {Number} status - The status of the query.
156:      * @param {Array} history - History data.
157:      * @returns {void}
158:      */
159:     function receiveHistory(status, history) {
160:         if (history === null) {
161:             return;
162:         }
163: 
164:         if (history.length === 0) {
165:             // Reached end of history
166:             window.onscroll = null;
167:             EOF_MESSAGE.style.display = "block";
168:             LOAD_LINK.style.display = "none";
169:             return;
170:         }
171: 
172:         nextTime = history[history.length - 1].time;
173:         nextOffset = 0;
174: 
175:         for (var i = 0, len = history.length; i < len; i++) {
176:             var item = history[i];
177:             // python's time.time returns seconds, but js Date expects ms
178:             var currentItemDate = new Date(item.time * 1000);
179:             getSessionNode(currentItemDate).appendChild(makeHistoryRow(
180:                 item.url, item.title, currentItemDate.toLocaleTimeString()
181:             ));
182:             lastItemDate = currentItemDate;
183:             if (item.time === nextTime) {
184:                 nextOffset++;
185:             }
186:         }
187:     }
188: 
189:     /**
190:      * Load new history.
191:      * @return {void}
192:      */
193:     function loadHistory() {
194:         var url = DATA_URL.concat("?offset=", nextOffset.toString());
195:         if (nextTime === null) {
196:             getJSON(url, receiveHistory);
197:         } else {
198:             url = url.concat("&start_time=", nextTime.toString());
199:             getJSON(url, receiveHistory);
200:         }
201:     }
202: 
203:     return loadHistory;
204: })();",
